import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type TreeGrowthProps = Record<string, any>;

const TreeGrowth: React.FC<TreeGrowthProps> = ({
  backgroundColor = "#87CEEB",
  transparentBackground = false,
  durationInSeconds = 10,
  totalDays = 365,
  treeTrunkColor = "#8B4513",
  foliageColor = "#228B22",
  groundColor = "#90EE90",
  counterColor = "#FFFFFF",
  appleColor = "#FF0000",
}) => {
  useFontLoader(["Rubik"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Logic to prevent parser errors ---
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  const totalFrames = durationInSeconds * fps;

  // --- Animation Drivers ---
  
  // 1. Growth Progress (Seedling -> Full Tree)
  // Instead of a fast spring, we grow over the duration of the "year"
  const growthDurationFrames = totalFrames * 0.8; // Grow for 80% of the time
  
  const rawGrowth = interpolate(frame, [0, growthDurationFrames], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Add a little springy overshoot at the very end of growth for realism
  const growthSpring = spring({
    frame: frame - growthDurationFrames,
    fps,
    config: { damping: 12, stiffness: 60 },
    from: 0,
    to: 0, // We use this just to check if we passed the mark, or we mix manual interp
  }); 
  // Simplified approach: Direct interpolation for the slow growth feels more like time-lapse
  // We map 0 -> 0.1 (seedling) to 1.0 (full tree)
  const treeScale = interpolate(frame, [0, growthDurationFrames], [0.1, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // 2. Apples Logic
  // Apples appear after the tree is grown (last 20% of timeline)
  const appleStartFrame = totalFrames * 0.8;
  const appleScale = spring({
    frame: frame - appleStartFrame,
    fps,
    config: { damping: 10, stiffness: 100 },
  });

  // 3. Day Counter (Linear interpolation)
  const currentDay = interpolate(
    frame,
    [0, totalFrames],
    [1, totalDays],
    {
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
    }
  );

  // 4. Wind / Breathing Effect (Slight sway)
  // Increases as tree gets bigger
  const windStrength = interpolate(treeScale, [0.1, 1], [0.2, 1]);
  const sway = Math.sin(frame / 20) * 2 * windStrength; 
  const leafSway = Math.sin(frame / 15) * 3 * windStrength;

  // --- Styles ---
  const containerStyle: React.CSSProperties = {
    backgroundColor: bgColor,
    fontFamily: "Rubik",
  };

  const groundHeight = height * 0.25;
  const treeBaseY = height - groundHeight;
  const treeCenterX = width * 0.5;

  return (
    <AbsoluteFill style={containerStyle}>
      
      {/* Day Counter */}
      <div
        style={{
          position: "absolute",
          top: width * 0.05,
          right: width * 0.05,
          fontSize: width * 0.06,
          fontWeight: "bold",
          color: counterColor,
          textAlign: "right",
          textShadow: "0px 2px 4px rgba(0,0,0,0.3)",
        }}
      >
        Day {Math.floor(currentDay)}
      </div>

      {/* Ground */}
      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          width: "100%",
          height: groundHeight,
          backgroundColor: groundColor,
          transformOrigin: "bottom center",
          transform: `scaleY(${spring({ frame: frame - 5, fps })})`,
        }}
      />

      {/* Tree SVG Container */}
      <svg
        width={width}
        height={height}
        style={{
          position: "absolute",
          overflow: "visible",
        }}
      >
        {/* Transform Group for Tree */}
        <g transform={`translate(${treeCenterX}, ${treeBaseY})`}>
          
          {/* Main Growth Scale Group */}
          {/* Moving origin to bottom center of tree for scaling up */}
          <g transform={`scale(${treeScale})`}>

            {/* Trunk */}
            <g transform={`rotate(${sway})`}>
              {/* Main Trunk Rect */}
              <path
                d="M -20 0 L -15 -150 L 15 -150 L 20 0 Z" 
                fill={treeTrunkColor}
              />
              
              {/* Left Branch */}
              <path
                d="M -15 -80 L -80 -140 L -70 -150 L -10 -90 Z"
                fill={treeTrunkColor}
                transform="scale(0.8)"
              />
              
              {/* Right Branch */}
              <path
                d="M 15 -100 L 90 -160 L 80 -170 L 10 -110 Z"
                fill={treeTrunkColor}
                transform="scale(0.8)"
              />
            </g>

            {/* Foliage Group */}
            {/* Attached to top of trunk roughly at -150 */}
            <g 
              transform={`translate(0, -150) rotate(${leafSway})`}
              // Foliage grows a bit faster relative to trunk to "pop" out
              style={{ 
                transformOrigin: "0 0", // Scale from connection point
              }}
            >
              {/* Main Top Cloud */}
              <circle cx="0" cy="-60" r="90" fill={foliageColor} />
              
              {/* Left Cloud */}
              <circle cx="-70" cy="-10" r="70" fill={foliageColor} />
              
              {/* Right Cloud */}
              <circle cx="70" cy="-20" r="75" fill={foliageColor} />
              
              {/* Top-Top Cloud */}
              <circle cx="20" cy="-110" r="60" fill={foliageColor} />
              
              {/* Filler Detail */}
              <circle cx="-30" cy="-60" r="50" fill={foliageColor} />

              {/* APPLES GROUP */}
              {/* Scaled by appleScale (spring) */}
              <g transform={`scale(${appleScale})`}>
                 <circle cx="-30" cy="-60" r="12" fill={appleColor} />
                 <circle cx="20" cy="-90" r="12" fill={appleColor} />
                 <circle cx="-50" cy="-20" r="12" fill={appleColor} />
                 <circle cx="50" cy="-40" r="12" fill={appleColor} />
                 <circle cx="0" cy="-120" r="12" fill={appleColor} />
                 <circle cx="60" cy="10" r="12" fill={appleColor} />
              </g>

            </g>

          </g>
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default TreeGrowth;